    function __ESBMC_assume(bool) internal pure {}

    function run(uint256 v) public {
        require(v > 0);
        require(v < 1000e18);
        c.XBornID(); if (__ESBMC_reverted()) return;
        require(c.balanceOf(address(this)) >= v);
        uint256 tsBefore = c.totalSupply(); if (__ESBMC_reverted()) return;
        uint256 tdBefore = c.totalDistributed(); if (__ESBMC_reverted()) return;
        c.burn(v); if (__ESBMC_reverted()) return;
        assert(c.totalSupply() == tsBefore - v && c.totalDistributed() == tdBefore - v);
    }

